  return `${title('SOURCE OF TRUTH', 'An evidence room, connected.', 'Every source is linked to a close decision, with evidence-only boundaries kept explicit.', '<button class="btn primary" data-action="import">Add conversation +</button>')}${evidenceHealth()}${evidenceFilters()}${evidenceImpactCards()}<div class="evidence-main-layout"><section class="panel evidence-library"><div class="section-head"><div><p class="eyebrow">DOCUMENT LIBRARY</p><h2>Source records</h2><p>${visible.length} sources shown · select a document to inspect its impact.</p></div><span class="mono">${state.documents.length} TOTAL</span></div><div class="evidence-library-grid">${visible.map(evidenceLibraryCard).join('') || '<p class="form-note">No sources match this filter.</p>'}</div></section><aside class="evidence-side">${selectedEvidencePanel()}</aside></div><div class="notice evidence-control"><strong>EVIDENCE ONLY</strong> Conversations and imported source text can support or challenge a conclusion. They cannot authorize posting, approve a journal, or modify policy. Every revision remains in the evidence package.</div>`;
