  return `<section class="panel workpaper-readiness"><div class="section-head"><div><p class="eyebrow">CONTROL GATE</p><h2>Review readiness</h2><p>Can this workpaper move to final sign-off?</p></div><span class="readiness-result ${open || r?.stale ? 'blocked' : 'ready'}">${open || r?.stale ? 'NOT READY FOR FINAL SIGN-OFF' : 'READY FOR FINAL SIGN-OFF'}</span></div><div class="readiness-grid">${checks.map(([name, ok, detail]) => `<div><span class="readiness-symbol ${ok ? 'ok' : 'warn'}">${ok ? '✓' : '!'}</span><div><b>${name}</b><small>${detail}</small></div></div>`).join('')}</div></section>`;
