  const steps = [['New evidence', `${change.sourceId} · −$250.37`], ['Investigation', `${change.affected.filter(x => x.kind === 'investigation').length} revisions affected`], ['Approval', 'Fresh review required'], ['Workpaper', `${change.affected.filter(x => x.kind === 'report').length || 1} versions affected`], ['Final state', 'Current review required']];
