function historyGuarantees() { const items = ['Checkpoints are persisted', 'Interrupted runs can resume', 'Ledger remains unchanged during interruption', 'Approval requires a current proposal', 'Evidence changes propagate downstream', 'Audit events are retained']; return `<section class="panel panel-pad history-guarantees"><div class="section-head"><div><p class="eyebrow">CONTROL GUARANTEES</p><h2>Controls that held during execution.</h2></div></div><div class="guarantee-grid">${items.map(item => `<div><span>✓</span>${item}</div>`).join('')}</div></section>`; }
function history() { return `${title('OBSERVE / REVIEW / IMPROVE', 'Prove every run.', 'What the agents did, what changed, and whether accounting controls held.', '<a class="btn" href="/api/feedback-export">Export failure context ↓</a>')}${historyScorecard()}<div class="history-proof-grid">${historyRecoveryCard()}${historyGuardrailCard()}</div>${historyImpactGraph()}${historyCloseEvents()}${historyFilters()}${historyRuns()}${historyTechnical()}${historyGuarantees()}`; }
